pub fn cleanupTempFile(name: [:0]const u8, fd: bun.FD) void {
        if (Environment.isPosix) {
            _ = Syscall.fchmod(fd, 511);
        }
        _ = fd.close();
        _ = Syscall.unlink(name);
}
